/* eslint-env jest */
'use strict';

const os = require('os');
const _ = require('lodash');

const yandexLogger = require('../../src');

describe('YandexLogger. Middleware. Secure TVM Headers', () => {
    let logger;
    let stream;
    let baseRecord;
    let jestFakeTimers;

    beforeEach(() => {
        stream = { write: jest.fn() };

        baseRecord = {
            pid: process.pid,
            date: expect.any(Date),
            name: 'yandex-logger',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msg: 'message',
            msgFormat: 'message',
            msgArgs: [],
        };

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();
    });

    it('должен обфусцировать TVM тикеты в req.headers', () => {
        logger = getLogger();

        let req = {
            headers: {
                ticket: 'TVM-1 Ticket',
                'x-ya-service-ticket': 'TVM 2 Service Ticket',
                'x-ya-user-ticket': 'TVM 2 User Ticket',
                authorization: 'Unknown Ticket',
            },
        };
        let reqClone = _.cloneDeep(req);
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                headers: {
                    ticket: 'TVM-1 XXXXXX',
                    'x-ya-service-ticket': 'TVM 2 ServXXXXXXXXXX',
                    'x-ya-user-ticket': 'TVM 2 UsXXXXXXXXX',
                    authorization: 'Unknown Ticket',
                },
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);

        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    it('должен принимать путь до заголовков', () => {
        logger = getLogger({ field: 'api.headers' });

        let api = {
            headers: {
                ticket: 'TVM-1 Ticket',
                'x-ya-service-ticket': 'TVM 2 Service Ticket',
                'x-ya-user-ticket': 'TVM 2 User Ticket',
                authorization: 'Unknown Ticket',
            },
        };
        let apiClone = _.cloneDeep(api);
        logger.info({ api }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            api: {
                headers: {
                    ticket: 'TVM-1 XXXXXX',
                    'x-ya-service-ticket': 'TVM 2 ServXXXXXXXXXX',
                    'x-ya-user-ticket': 'TVM 2 UsXXXXXXXXX',
                    authorization: 'Unknown Ticket',
                },
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);

        expect(api).toStrictEqual(apiClone, 'Оригинальный объект не должен мутировать');
    });

    it('не должен падать без заголовков в req.headers', () => {
        logger = getLogger();

        let req = {
            headers: {},
        };
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                headers: {},
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    function getLogger(config) {
        return yandexLogger({
            streams: [
                { stream },
            ],
            middleware: [
                require('../../middleware/secure-tvm-headers')(config),
            ],
        });
    }
});
